{
  "schema_version": 1,
  "template_id": "product-feedback-coordinator",
  "template_version": 2,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm product owner and Crew identity",
      "instructions": "Confirm whether this capability seeds a Product Crew or extends a compatible Crew. Preserve existing identity and name the accountable product decision owner."
    },
    {
      "id": "skill",
      "title": "Verify selected skill",
      "instructions": "Confirm skills/product-feedback-coordinator/SKILL.md exists and product-feedback-coordinator is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Bind product evidence scope",
      "instructions": "Record tenant, product, feature or journey, period, affected segment, exact feedback theme or adoption artifact ID and owner. Minimum input: Validated feedback theme or feature-adoption observation, exact product and segment, current issue/release source, product owner and decision criteria."
    },
    {
      "id": "access",
      "title": "Probe authorized product sources",
      "instructions": "Read one real feedback theme or validated feature observation plus current issue/release state. Record source IDs, timestamps, permissions and gaps. Helpdesk/survey exports, product usage and exposure records, release/flag source, issue tracker and roadmap through scoped MCPs or files. A read-only first decision uses authorized exports."
    },
    {
      "id": "policy",
      "title": "Agree on decision and privacy rules",
      "instructions": "For feedback, confirm prevalence and counterexamples; for feature adoption, freeze release, exposure denominator, measurement rule, target and coverage threshold. Record strategic criteria, privacy limits and action authority. Do not promise a feature, rank a roadmap by mention count alone, create or close an issue, change priority, publish a plan, or message a customer without owner approval and a separate route."
    },
    {
      "id": "first_result",
      "title": "Produce a sourced first decision brief",
      "instructions": "Produce A product decision brief with exact source artifact, affected scope, current issue state, evidence gaps, owner options and next verification. Cite each claim, applicable denominator, release and source revision. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review with product owner",
      "instructions": "Show representative and contrary evidence, exact existing issue match, unknowns, options and recommended next investigation. Record the owner decision or correction."
    },
    {
      "id": "delivery",
      "title": "Choose read-only or issue route",
      "optional": true,
      "instructions": "Read-only chat completes this choice. Any issue creation, status change or customer communication needs a separately approved exact-object route and provider receipt."
    },
    {
      "id": "recurrence",
      "title": "Choose manual or recurring review",
      "optional": true,
      "instructions": "Manual-only completes this choice. A schedule or authenticated event requires reviewed source scope, stable theme or feature IDs, deduplication, cost and notification rules. Re-read current issue, roadmap, release and product evidence; retain theme or feature observation IDs, rule versions and owner decisions, and report changes instead of opening duplicate work."
    }
  ],
  "completed_steps": []
}
